/**
 * The portal index of an ejected project (ADR 0077 D5, D9), in `<package>/portal/`: copies of the
 * runtime's `PortalIndex` and `PortalIndexAttachment`
 * (`engine-mod/src/main/java/dev/mcsupermods/runtime/registry/portal/`, Minecraft 26.3, Mojang
 * names). The attachment is `<mod id>:portals` (the runtime's is `msm_runtime:portals`, so links
 * made with the runtime are not read by the ejected mod: new exits are built), it logs through
 * its own logger, and the saved entry is read with vanilla's `fieldOf` (the runtime's `MsmCodecs`
 * is not ejected: other keys are ignored rather than rejected). The generator's tests compare
 * every other code line with the runtime's.
 *
 * @packageDocumentation
 */

import { javaString } from '../java';

/** The source of `PortalIndex.java`, copied from the runtime's `PortalIndex`. */
export function portalIndexJava(portalPackage: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's PortalIndex.
package ${portalPackage};

import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.function.Predicate;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.resources.Identifier;

/**
 * The portals of one level (ADR 0077 D5): one {@link Entry} per lit or built portal, the inside rectangle and the portal
 * block's id. Immutable; {@link PortalIndexAttachment} stores it as the persistent {@code ServerLevel} attachment
 * {@code <mod id>:portals}. Entries are kept sorted by block, then position, so the saved form is stable.
 */
public record PortalIndex(List<Entry> entries) {
    // Before EMPTY: the constructor sorts with it.
    private static final Comparator<Entry> ORDER = Comparator.comparing((Entry e) -> e.block().toString())
            .thenComparingInt(e -> e.min().getX()).thenComparingInt(e -> e.min().getY()).thenComparingInt(e -> e.min().getZ())
            .thenComparing(e -> e.axis().getSerializedName());

    /** No portals; the attachment is removed rather than saved empty. */
    public static final PortalIndex EMPTY = new PortalIndex(List.of());

    /** One portal: {@code min} is the lowest inside block ({@link PortalFrame.Rectangle#min()}). */
    public record Entry(Identifier block, BlockPos min, Direction.Axis axis, int width, int height) {
        /** The saved form {@code { block, min, axis, width, height }} (other keys are ignored; the runtime rejects them). */
        public static final Codec<Entry> CODEC = RecordCodecBuilder.create(i -> i.group(
                Identifier.CODEC.fieldOf("block").forGetter(Entry::block),
                BlockPos.CODEC.fieldOf("min").forGetter(Entry::min),
                Direction.Axis.CODEC.validate(a -> a == Direction.Axis.Y
                        ? DataResult.error(() -> "a portal axis is x or z")
                        : DataResult.success(a)).fieldOf("axis").forGetter(Entry::axis),
                Codec.intRange(PortalFrame.MIN_WIDTH, PortalFrame.MAX_WIDTH).fieldOf("width").forGetter(Entry::width),
                Codec.intRange(PortalFrame.MIN_HEIGHT, PortalFrame.MAX_HEIGHT).fieldOf("height").forGetter(Entry::height))
                .apply(i, Entry::new));

        public Entry {
            min = min.immutable();
        }

        /** The entry for a portal of {@code block} filling {@code rectangle}. */
        public static Entry of(Identifier block, PortalFrame.Rectangle rectangle) {
            return new Entry(block, rectangle.min(), rectangle.axis(), rectangle.width(), rectangle.height());
        }

        /** The inside rectangle. */
        public PortalFrame.Rectangle rectangle() {
            return new PortalFrame.Rectangle(min, axis, width, height);
        }

        /**
         * The inside block closest to {@code target}: {@code target} clamped to the rectangle on each coordinate. Used for
         * the search radius and the distance, so a wide portal counts from its nearest block.
         */
        public BlockPos closestTo(BlockPos target) {
            BlockPos max = rectangle().max();
            return new BlockPos(clamp(target.getX(), min.getX(), max.getX()), clamp(target.getY(), min.getY(), max.getY()),
                    clamp(target.getZ(), min.getZ(), max.getZ()));
        }

        private static int clamp(int value, int low, int high) {
            return Math.max(low, Math.min(high, value));
        }
    }

    /** The saved form: a list of entries. */
    public static final Codec<PortalIndex> CODEC = Entry.CODEC.listOf().xmap(PortalIndex::new, PortalIndex::entries);

    public PortalIndex {
        entries = entries.stream().sorted(ORDER).toList();
    }

    public boolean isEmpty() {
        return entries.isEmpty();
    }

    /**
     * This index with {@code entry}; an entry of the same block whose rectangle shares a block with it is replaced (a
     * portal relit in a resized frame, or indexed twice).
     */
    public PortalIndex with(Entry entry) {
        List<Entry> out = new ArrayList<>();
        for (Entry e : entries) {
            if (!(e.block().equals(entry.block()) && overlaps(e, entry))) {
                out.add(e);
            }
        }
        out.add(entry);
        return new PortalIndex(out);
    }

    /** This index without {@code entry} (equal entries only). */
    public PortalIndex without(Entry entry) {
        return new PortalIndex(entries.stream().filter(e -> !e.equals(entry)).toList());
    }

    /** The entry of {@code block} whose inside holds {@code pos}, if any. */
    public Optional<Entry> at(Identifier block, BlockPos pos) {
        return entries.stream().filter(e -> e.block().equals(block) && e.rectangle().contains(pos)).findFirst();
    }

    /**
     * The entries of {@code block} within the square {@code radius} of {@code target} (x and z of the closest inside
     * block at most {@code radius} away; any height), whose closest block passes {@code inBounds} (the world border),
     * closest first by squared distance, then lowest y, then the saved order.
     */
    public List<Entry> candidates(Identifier block, BlockPos target, int radius, Predicate<BlockPos> inBounds) {
        record Scored(Entry entry, BlockPos closest, long distance) {}
        List<Scored> scored = new ArrayList<>();
        for (Entry e : entries) {
            if (!e.block().equals(block)) {
                continue;
            }
            BlockPos closest = e.closestTo(target);
            if (Math.abs(closest.getX() - target.getX()) > radius || Math.abs(closest.getZ() - target.getZ()) > radius
                    || !inBounds.test(closest)) {
                continue;
            }
            scored.add(new Scored(e, closest, (long) Math.round(closest.distSqr(target))));
        }
        scored.sort(Comparator.comparingLong(Scored::distance).thenComparingInt(s -> s.entry().min().getY()));
        return scored.stream().map(Scored::entry).toList();
    }

    private static boolean overlaps(Entry a, Entry b) {
        BlockPos aMax = a.rectangle().max();
        BlockPos bMax = b.rectangle().max();
        return a.min().getX() <= bMax.getX() && b.min().getX() <= aMax.getX() && a.min().getY() <= bMax.getY()
                && b.min().getY() <= aMax.getY() && a.min().getZ() <= bMax.getZ() && b.min().getZ() <= aMax.getZ();
    }
}
`;
}

/** The source of `PortalIndexAttachment.java`, copied from the runtime's `PortalIndexAttachment`. */
export function portalIndexAttachmentJava(portalPackage: string, modId: string): string {
  return `// Generated by MCSuperMods: copied from msm_runtime's PortalIndexAttachment.
package ${portalPackage};

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.fabricmc.fabric.api.attachment.v1.AttachmentRegistry;
import net.fabricmc.fabric.api.attachment.v1.AttachmentType;
import net.minecraft.core.BlockPos;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.Block;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * The persistent Fabric attachment {@code <mod id>:portals} (ADR 0077 D5) holding each {@code ServerLevel}'s {@link
 * PortalIndex}. Fabric saves level attachments in that level's saved data {@code fabric:attachments} (the file
 * {@code data/fabric/attachments.dat} in the level's own data folder); not synced to clients. Registered once, from
 * the mod initialiser. Entries whose block at {@code min} is no longer the portal's block are dropped when a lookup meets
 * them.
 */
public final class PortalIndexAttachment {
    private static final String MOD_ID = ${javaString(modId)};
    private static final Logger LOGGER = LoggerFactory.getLogger(MOD_ID);
    public static final Identifier ID = Identifier.fromNamespaceAndPath(MOD_ID, "portals");

    public static final AttachmentType<PortalIndex> TYPE = AttachmentRegistry.create(ID, builder -> builder.persistent(PortalIndex.CODEC));

    private PortalIndexAttachment() {}

    /** Registers the attachment type (class initialisation); called from the mod initialiser. */
    public static void register() {
        LOGGER.debug("[{}] registered attachment {}", MOD_ID, TYPE.identifier());
    }

    /** The level's index, or {@link PortalIndex#EMPTY}. */
    public static PortalIndex get(ServerLevel level) {
        return level.getAttachedOrElse(TYPE, PortalIndex.EMPTY);
    }

    /** Stores the index; an empty index removes the attachment, so nothing is saved for it. */
    public static void set(ServerLevel level, PortalIndex index) {
        if (index.isEmpty()) {
            level.removeAttached(TYPE);
        } else {
            level.setAttached(TYPE, index);
        }
    }

    /** The registry id of a portal block. */
    public static Identifier id(Block portal) {
        return BuiltInRegistries.BLOCK.getKey(portal);
    }

    /** Records a lit or built portal of {@code portal} filling {@code rectangle}; returns its entry. */
    public static PortalIndex.Entry add(ServerLevel level, Block portal, PortalFrame.Rectangle rectangle) {
        PortalIndex.Entry entry = PortalIndex.Entry.of(id(portal), rectangle);
        add(level, entry);
        return entry;
    }

    /** Records {@code entry}, replacing an overlapping entry of the same block. */
    public static void add(ServerLevel level, PortalIndex.Entry entry) {
        set(level, get(level).with(entry));
    }

    /** Forgets {@code entry}. */
    public static void remove(ServerLevel level, PortalIndex.Entry entry) {
        set(level, get(level).without(entry));
    }

    /** Whether the block at the entry's {@code min} is still the entry's portal block (loads that chunk). */
    public static boolean isPresent(ServerLevel level, PortalIndex.Entry entry) {
        return id(level.getBlockState(entry.min()).getBlock()).equals(entry.block());
    }

    /** The entry of {@code portal} whose inside holds {@code pos}, if it is indexed and still present (else dropped). */
    public static Optional<PortalIndex.Entry> at(ServerLevel level, Block portal, BlockPos pos) {
        Optional<PortalIndex.Entry> entry = get(level).at(id(portal), pos);
        if (entry.isPresent() && !isPresent(level, entry.get())) {
            remove(level, entry.get());
            return Optional.empty();
        }
        return entry;
    }

    /**
     * The nearest present portal of {@code block} within the square {@code radius} of {@code target} and inside the
     * level's world border (closest by distance, then lowest y); stale entries met on the way are dropped from the index.
     */
    public static Optional<PortalIndex.Entry> nearest(ServerLevel level, Identifier block, BlockPos target, int radius) {
        PortalIndex index = get(level);
        List<PortalIndex.Entry> stale = new ArrayList<>();
        Optional<PortalIndex.Entry> found = Optional.empty();
        for (PortalIndex.Entry entry : index.candidates(block, target, radius, level.getWorldBorder()::isWithinBounds)) {
            if (isPresent(level, entry)) {
                found = Optional.of(entry);
                break;
            }
            stale.add(entry);
        }
        if (!stale.isEmpty()) {
            PortalIndex pruned = index;
            for (PortalIndex.Entry entry : stale) {
                pruned = pruned.without(entry);
            }
            set(level, pruned);
        }
        return found;
    }
}
`;
}
